fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Create a new vector to hold the result
    let mut new_list = Vec::with_capacity(list.len() - 1);
    
    // Iterate through the original list
    for (i, &value) in list.iter().enumerate() {
        // Only add elements that are not at the k-1 index (0-based)
        if i != k - 1 {
            new_list.push(value);
        }
    }
    
    new_list
}